/**
 * Hermes desktop widget for the `quota` plugin.
 *
 * Status bar:
 *   - 'all' mode: one chip per configured provider, side by side.
 *   - 'worst' mode: single chip with worst remaining % + tonal bar.
 *   - Both respect "Show status bar" setting.
 *
 * Route /quota (full pane) + docked right pane + sidebar nav.
 *
 * Data path: host.requestProfile(route, 'cli.exec', {argv: ['quota', 'status', '--json']})
 *   → focused profile's Hermes CLI → quota_cache.json (offline, fast).
 * Refresh: host.requestProfile(route, 'cli.exec', {argv: ['quota', 'refresh']}).
 *
 * SINGLE SOURCE FILE: keep only at <hermes home>/desktop-plugins/quota/plugin.js.
 * Do NOT also place a copy under profiles/<name>/desktop-plugins/quota.
 *
 * Plain ESM, loaded uncompiled — UI is jsx() calls. Only these imports
 * resolve: @hermes/plugin-sdk, react, react/jsx-runtime. `ctx` comes from
 * register(ctx), not from an import.
 */

import {
	atom,
	cn,
	ConfirmDialog,
	host,
	Input,
	icons,
	PANES_AREA,
	Popover,
	PopoverContent,
	PopoverTrigger,
	queryClient,
	ROUTES_AREA,
	SegmentedControl,
	SIDEBAR_NAV_AREA,
	STATUSBAR_AREAS,
	StatusDot,
	Switch,
	Tip,
	useI18n,
	useMutation,
	usePluginI18n,
	useQuery,
	useQueryClient,
	useValue,
} from "@hermes/plugin-sdk";
import { useEffect, useMemo, useRef, useState } from "react";
import { jsx, jsxs } from "react/jsx-runtime";

const ID = "quota";

// This widget's build. It must equal `version:` in plugin.yaml — the desktop app
// loads the widget from the CLIENT machine while `cli.exec` runs against the
// gateway, so the two halves can really be different builds. `tests/test_widget_version.py`
// fails when they drift; a mismatch found at runtime is surfaced in the pane
// instead of looking like a broken feature.
const WIDGET_VERSION = "3.1.0";

// Module-level ctx handle (set in register). The data hook below needs it.
let CTX = null;

// ---- locale: app language → Intl --------------------------------------------
//
// Dates, numbers and money follow the APP language (display.language), never
// the OS locale: `Intl.*(undefined)` / `toLocaleString([])` show English dates
// in a Turkish UI. Components report the reactive `useI18n().locale` while they
// render (useQT); code outside React falls back to the bundle's `_locale` key
// through ctx.i18n.t, then to <html lang> (the app sets it with the language).

const INTL_TAGS = {
	en: "en-US",
	tr: "tr-TR",
	de: "de-DE",
	es: "es-ES",
	fr: "fr-FR",
	ru: "ru-RU",
	ja: "ja-JP",
	zh: "zh-CN",
	"zh-hant": "zh-TW",
	// Western digits: the strings around these numbers (and the app) use them.
	ar: "ar-u-nu-latn",
};
const RTL_LANGS = new Set(["ar", "fa", "he", "ur", "ps", "yi"]);
let _renderLocale = null;

function normLocale(value) {
	return typeof value === "string" && value.trim() ? value.trim().replace(/_/g, "-").toLowerCase() : null;
}

/** The app's active language id ("tr", "zh-hant", …). */
function appLocale() {
	if (_renderLocale) return _renderLocale;
	let id = null;
	try {
		const v = CTX && CTX.i18n && typeof CTX.i18n.t === "function" ? CTX.i18n.t("_locale") : null;
		if (v && v !== "_locale") id = normLocale(v);
	} catch {
		/* older host */
	}
	if (!id || id === "en") {
		try {
			const lang = typeof document !== "undefined" && document.documentElement ? normLocale(document.documentElement.lang) : null;
			if (lang) id = lang;
		} catch {
			/* no DOM */
		}
	}
	return id || "en";
}

function noteRenderLocale(locale) {
	const id = normLocale(locale);
	if (id) _renderLocale = id;
}

/** BCP-47 tag for Intl (tr → tr-TR, zh-hant → zh-TW, ar → Western digits). */
function intlTag(id = appLocale()) {
	if (INTL_TAGS[id]) return INTL_TAGS[id];
	if (/^zh-(tw|hk|mo|hant)/.test(id)) return INTL_TAGS["zh-hant"];
	const base = id.split("-")[0];
	if (base === "ar") return INTL_TAGS.ar;
	try {
		if (Intl.DateTimeFormat.supportedLocalesOf([id]).length) return id;
	} catch {
		/* malformed tag */
	}
	return INTL_TAGS[base] || "en-US";
}

function localeBase() {
	return appLocale().split("-")[0];
}

function isEnLocale() {
	return localeBase() === "en";
}

function isRtl() {
	return RTL_LANGS.has(localeBase());
}

/** `dir` for the plugin's roots (the app also sets it on <html>). */
function localeDir() {
	return isRtl() ? "rtl" : "ltr";
}

/** A "leads to" arrow that points along the reading direction. */
function arrowFwd() {
	return isRtl() ? "←" : "→";
}

// Hermes' configured IANA timezone (`timezone` on the quota payload; "" =
// the host zone). The app LANGUAGE picks the date format; this picks the
// wall clock, so every timestamp matches the CLI and TUI.
let _dataTimeZone = "";

function validTimeZone(zone) {
	if (typeof zone !== "string" || !zone.trim()) return "";
	try {
		new Intl.DateTimeFormat("en-US", { timeZone: zone.trim() });
		return zone.trim();
	} catch {
		return "";
	}
}

function noteDataTimeZone(data) {
	if (data && typeof data === "object" && !Array.isArray(data) && "timezone" in data) {
		_dataTimeZone = validTimeZone(data.timezone);
	}
}

const _intlCache = new Map();
function intl(kind, options = {}) {
	const tag = intlTag();
	// An explicit `timeZone` (even "UTC" for calendar-day labels) wins.
	const opts = kind === "DateTimeFormat" && options.timeZone === undefined && _dataTimeZone
		? { ...options, timeZone: _dataTimeZone }
		: options;
	const key = `${kind}|${tag}|${JSON.stringify(opts)}`;
	let f = _intlCache.get(key);
	if (!f) {
		try {
			f = new Intl[kind](tag, opts);
		} catch {
			try {
				f = new Intl[kind]("en-US", opts);
			} catch {
				// Unknown zone: the app language still applies, host clock.
				const { timeZone: _ignored, ...rest } = opts;
				f = new Intl[kind](tag, rest);
			}
		}
		_intlCache.set(key, f);
	}
	return f;
}

/** usePluginI18n + the reactive app locale for the formatters below. */
function useQT() {
	let locale = null;
	if (typeof useI18n === "function") {
		try {
			const i18n = useI18n();
			locale = i18n && i18n.locale;
		} catch {
			locale = null;
		}
	}
	if (locale) noteRenderLocale(locale);
	return usePluginI18n(ID);
}

// ---- persisted settings (ctx.storage + useValue atoms) -------------------

const RESET_FORMAT_KEY = "resetFormat"; // 'relative' | 'absolute'
const RESET_FORMAT_DEFAULT = "relative";

const resetFormatAtom = atom(RESET_FORMAT_DEFAULT);

function readStored(key, fallback) {
	try {
		const v = CTX.storage.get(key);
		return v == null ? fallback : v;
	} catch {
		return fallback;
	}
}

function applyStored(key, atomRef, allowed, fallback) {
	try {
		const v = CTX.storage.get(key);
		atomRef.set(allowed.includes(v) ? v : fallback);
	} catch {
		/* noop */
	}
}

function setStored(key, value, atomRef) {
	try {
		CTX.storage.set(key, value);
		atomRef.set(value);
	} catch {
		/* noop */
	}
}

function applyStoredResetFormat() {
	applyStored(
		RESET_FORMAT_KEY,
		resetFormatAtom,
		["relative", "absolute"],
		RESET_FORMAT_DEFAULT,
	);
}

function setResetFormat(fmt) {
	setStored(RESET_FORMAT_KEY, fmt, resetFormatAtom);
}

// Cherry-picker: list of disabled provider IDs (persisted).
const DISABLED_PROVIDERS_KEY = "disabledProviders";
const DISABLED_PROVIDERS_DEFAULT = []; // empty = all enabled

const disabledProvidersAtom = atom(DISABLED_PROVIDERS_DEFAULT);

function applyStoredDisabledProviders() {
	try {
		const v = CTX.storage.get(DISABLED_PROVIDERS_KEY);
		disabledProvidersAtom.set(
			Array.isArray(v) ? v : DISABLED_PROVIDERS_DEFAULT,
		);
	} catch {
		/* noop */
	}
}

function setDisabledProviders(list) {
	setStored(DISABLED_PROVIDERS_KEY, list, disabledProvidersAtom);
}

function isProviderEnabled(pid) {
	const disabled = disabledProvidersAtom.get();
	return !disabled.includes(pid);
}

// Surface toggles: status bar on by default; docked pane off by default.
const SHOW_STATUSBAR_KEY = "showStatusBar";
const SHOW_STATUSBAR_DEFAULT = true;
const SHOW_DOCKED_PANE_KEY = "showDockedPane";
const SHOW_DOCKED_PANE_DEFAULT = false;

const showStatusBarAtom = atom(SHOW_STATUSBAR_DEFAULT);
const showDockedPaneAtom = atom(SHOW_DOCKED_PANE_DEFAULT);

function applyStoredBoolean(key, atomRef, fallback) {
	try {
		atomRef.set(readStored(key, fallback) === true);
	} catch {
		/* noop */
	}
}

function applyStoredSurfaceVisibility() {
	applyStoredBoolean(
		SHOW_STATUSBAR_KEY,
		showStatusBarAtom,
		SHOW_STATUSBAR_DEFAULT,
	);
	applyStoredBoolean(
		SHOW_DOCKED_PANE_KEY,
		showDockedPaneAtom,
		SHOW_DOCKED_PANE_DEFAULT,
	);
}

function setShowStatusBar(v) {
	setStored(SHOW_STATUSBAR_KEY, !!v, showStatusBarAtom);
}

function setShowDockedPane(v) {
	setStored(SHOW_DOCKED_PANE_KEY, !!v, showDockedPaneAtom);
	if (showDockedPaneAtom.get()) {
		registerDockedPane();
	} else {
		clearDockedPane();
	}
}

// statusbarMode: 'all' renders every configured provider side by side;
// 'worst' renders the single worst-provider chip (previous behaviour).
const STATUSBAR_MODE_KEY = "statusbarMode";
const STATUSBAR_MODE_DEFAULT = "all";

const statusbarModeAtom = atom(STATUSBAR_MODE_DEFAULT);

// paneDetail: 'dense' shows every window, reset time and detail line per
// provider; 'clean' collapses to just the percentage bars (label + % left).
const PANE_DETAIL_KEY = "paneDetail";
const PANE_DETAIL_DEFAULT = "dense";

const paneDetailAtom = atom(PANE_DETAIL_DEFAULT);

function applyStoredStatusbarMode() {
	applyStored(
		STATUSBAR_MODE_KEY,
		statusbarModeAtom,
		["all", "worst"],
		STATUSBAR_MODE_DEFAULT,
	);
}

function setStatusbarMode(mode) {
	setStored(STATUSBAR_MODE_KEY, mode, statusbarModeAtom);
}

function applyStoredPaneDetail() {
	applyStored(PANE_DETAIL_KEY, paneDetailAtom, ["clean", "dense"], PANE_DETAIL_DEFAULT);
}

function setPaneDetail(mode) {
	setStored(PANE_DETAIL_KEY, mode, paneDetailAtom);
}

// refreshInterval: statusbar/pane poll cadence in seconds (persisted as number).
const REFRESH_INTERVAL_KEY = "refreshInterval";
const REFRESH_INTERVAL_DEFAULT = 600;
const REFRESH_INTERVAL_MIN = 15;
const REFRESH_INTERVAL_MAX = 600;

const refreshIntervalAtom = atom(REFRESH_INTERVAL_DEFAULT);

function applyStoredRefreshInterval() {
	try {
		const v = CTX.storage.get(REFRESH_INTERVAL_KEY);
		const n = Number(v);
		const clamped = isNaN(n)
			? REFRESH_INTERVAL_DEFAULT
			: Math.max(
					REFRESH_INTERVAL_MIN,
					Math.min(REFRESH_INTERVAL_MAX, Math.round(n)),
				);
		refreshIntervalAtom.set(clamped);
	} catch {
		/* noop */
	}
}

function setRefreshInterval(seconds) {
	const n = Number(seconds);
	const clamped = isNaN(n)
		? REFRESH_INTERVAL_DEFAULT
		: Math.max(
				REFRESH_INTERVAL_MIN,
				Math.min(REFRESH_INTERVAL_MAX, Math.round(n)),
			);
	setStored(REFRESH_INTERVAL_KEY, clamped, refreshIntervalAtom);
}

// Apply every persisted setting from storage on plugin load.
function applyStoredAll() {
	applyStoredResetFormat();
	applyStoredSurfaceVisibility();
	applyStoredStatusbarMode();
	applyStoredPaneDetail();
	applyStoredRefreshInterval();
	applyStoredDisabledProviders();
	applyStoredMonitor();
}

